INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_hud-zvuk-rytmus_0','Čím vzniká zvuk?',ARRAY['Chvěním (kmitáním) předmětů','Barvou','Světlem','Teplem']::TEXT[],0,'Zvuk vzniká chvěním zdroje zvuku.',1,ARRAY[]::TEXT[],NULL,0,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_1','Co znamená slovo „forte“?',ARRAY['Pomalu','Rychle','Tiše','Silně']::TEXT[],3,'Forte (f) značí silnou hru či zpěv.',1,ARRAY[]::TEXT[],NULL,1,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_2','Co znamená slovo „piano“?',ARRAY['Dlouze','Rychle','Silně','Tiše']::TEXT[],3,'Piano (p) značí tichou hru či zpěv.',1,ARRAY[]::TEXT[],NULL,2,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_3','Kterým orgánem slyšíme zvuk?',ARRAY['Jazykem','Uchem','Nosem','Okem']::TEXT[],1,'Sluch zajišťuje ucho.',1,ARRAY[]::TEXT[],NULL,3,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_4','Který nástroj je bicí?',ARRAY['Klarinet','Flétna','Buben','Housle']::TEXT[],2,'Na bicí nástroje se hraje úderem.',1,ARRAY[]::TEXT[],NULL,4,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_5','Čím se liší tón od šumu?',ARRAY['Tón má určitou výšku, šum ne','Nijak','Šum je vždy tichý','Tón je vždy hlasitý']::TEXT[],0,'Tón je pravidelné kmitání, šum nepravidelné.',2,ARRAY[]::TEXT[],NULL,5,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_6','Co je to rytmus?',ARRAY['Pravidelné střídání dlouhých a krátkých zvuků','Výška tónu','Barva zvuku','Hlasitost']::TEXT[],0,'Rytmus určuje časové uspořádání zvuků.',2,ARRAY[]::TEXT[],NULL,6,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_7','Co je tempo?',ARRAY['Hlasitost','Barva zvuku','Rychlost hudby','Výška tónu']::TEXT[],2,'Tempo udává, jak rychle hudba plyne.',2,ARRAY[]::TEXT[],NULL,7,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_8','Která dvojice znamená „rychle“ a „pomalu“?',ARRAY['Allegro – largo','Dolce – brillante','Piano – forte','Staccato – legato']::TEXT[],0,'Allegro je rychlé, largo velmi pomalé.',2,ARRAY[]::TEXT[],NULL,8,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_9','Co znamená „crescendo“?',ARRAY['Zpomalovat','Zrychlovat','Postupně zesilovat','Postupně zeslabovat']::TEXT[],2,'Crescendo je zesilování, decrescendo zeslabování.',2,ARRAY[]::TEXT[],NULL,9,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_10','Co znamená „decrescendo“?',ARRAY['Postupně zeslabovat','Zrychlovat','Odmlčet se','Zesilovat']::TEXT[],0,'Decrescendo je postupné zeslabování.',2,ARRAY[]::TEXT[],NULL,10,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_11','Co je to melodie?',ARRAY['Hluk','Řada tónů uspořádaných za sebou v rytmu','Jediný tón','Rytmus bez výšky']::TEXT[],1,'Melodie má různé výšky a rytmus.',3,ARRAY[]::TEXT[],NULL,11,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_12','Jak se nazývá hudba hraná jedním hlasem bez doprovodu?',ARRAY['Duo','Sólo','Chór','Orchestr']::TEXT[],1,'Sólista hraje či zpívá sám.',3,ARRAY[]::TEXT[],NULL,12,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_13','Kolik hráčů hraje v triu?',ARRAY['3','2','5','4']::TEXT[],0,'Trio je skladba pro tři.',3,ARRAY[]::TEXT[],NULL,13,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_14','Co znamená „staccato“?',ARRAY['Pomalu','Krátce, oddělené tóny','Tiše','Plynule spojovat']::TEXT[],1,'Staccato jsou krátké oddělené tóny.',3,ARRAY[]::TEXT[],NULL,14,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_15','Co znamená „legato“?',ARRAY['Spojovat tóny','Zrychlovat','Zesilovat','Oddělovat tóny']::TEXT[],0,'Legato je plynulé vázání tónů.',3,ARRAY[]::TEXT[],NULL,15,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_16','Která nota trvá půl doby?',ARRAY['Čtvrťová','Půlová','Celá','Osminová']::TEXT[],3,'Osminová nota trvá půl doby (čtvrťová = 1 doba).',4,ARRAY[]::TEXT[],NULL,16,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_17','Jaký je poměr půlové a čtvrťové noty?',ARRAY['1 půlová = 2 čtvrťové','1 půlová = 4 čtvrťové','1 půlová = 1 čtvrťová','1 půlová = 3 čtvrťové']::TEXT[],0,'Půlová nota trvá 2 doby.',4,ARRAY[]::TEXT[],NULL,17,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_18','Kolik dob trvá celá nota?',ARRAY['2','4','8','1']::TEXT[],1,'Celá nota trvá čtyři doby.',4,ARRAY[]::TEXT[],NULL,18,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_19','Co je to pomlka?',ARRAY['Druh nástroje','Znaménko označující ticho v hudbě','Druh tónu','Nota']::TEXT[],1,'Pomlka značí dobu bez tónu.',4,ARRAY[]::TEXT[],NULL,19,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_20','Co znamená „andante“?',ARRAY['Velmi rychle','Krokem, mírně pomalu','Zesílit','Zeslabit']::TEXT[],1,'Andante je mírné pomalé tempo.',4,ARRAY[]::TEXT[],NULL,20,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_21','Co znamená značka mf?',ARRAY['Středně silně (mezzoforte)','Velmi tiše','Rychle','Velmi silně']::TEXT[],0,'Mezzoforte je středně silně.',5,ARRAY[]::TEXT[],NULL,21,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_22','Který výraz označuje velmi rychlé tempo?',ARRAY['Lento','Adagio','Largo','Presto']::TEXT[],3,'Presto je velmi rychlé.',5,ARRAY[]::TEXT[],NULL,22,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_23','Co je to metrum?',ARRAY['Pravidelné střídání těžkých a lehkých dob','Barva zvuku','Výška tónu','Hlasitost']::TEXT[],0,'Metrum určuje takt.',5,ARRAY[]::TEXT[],NULL,23,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-zvuk-rytmus_24','Jaké je tempo označení „allegro“?',ARRAY['Majestátně','Velmi tiše','Rychle, živě','Pomalu']::TEXT[],2,'Allegro znamená rychle a svižně.',5,ARRAY[]::TEXT[],NULL,24,'c_hud-zvuk-rytmus',NULL,NOW()),
('q_hud-noty-osnova_0','Kolik linek má notová osnova?',ARRAY['3','6','4','5']::TEXT[],3,'Osnova má pět linek a čtyři mezery.',1,ARRAY[]::TEXT[],NULL,0,'c_hud-noty-osnova',NULL,NOW()),
