('q_hud-noty-osnova_4','Na které lince leží tón g¹ v houslovém klíči?',ARRAY['Na první','Na druhé','Na páté','Na třetí']::TEXT[],1,'Houslový klíč se otáčí kolem druhé linky.',2,ARRAY[]::TEXT[],NULL,4,'c_hud-noty-osnova',NULL,NOW()),
('q_hud-noty-osnova_5','Jak se počítají linky osnovy?',ARRAY['Zleva doprava','Shora dolů','Zdola nahoru','Podle barvy']::TEXT[],2,'První linka je nejníže.',2,ARRAY[]::TEXT[],NULL,5,'c_hud-noty-osnova',NULL,NOW()),
