('q_hud-noty-osnova_10','Co dělá znaménko ♭ (béčko)?',ARRAY['Snižuje tón o půltón','Zkracuje tón','Zvyšuje tón o půltón','Zesiluje tón']::TEXT[],0,'Béčko snižuje tón o půltón.',3,ARRAY[]::TEXT[],NULL,10,'c_hud-noty-osnova',NULL,NOW()),
