('q_hud-noty-osnova_12','Co udává horní číslo v zápisu taktu 3/4?',ARRAY['Dynamiku','Hodnotu doby','Tempo','Počet dob v taktu']::TEXT[],3,'Horní číslo je počet dob.',3,ARRAY[]::TEXT[],NULL,12,'c_hud-noty-osnova',NULL,NOW()),
