('q_hud-noty-osnova_19','Co znamená značka repetice (dvojtečka u taktové čáry)?',ARRAY['Dynamika','Konec skladby','Tempo','Opakování úseku']::TEXT[],3,'Repetice vyžaduje zopakovat úsek.',4,ARRAY[]::TEXT[],NULL,19,'c_hud-noty-osnova',NULL,NOW()),
